$ErrorActionPreference='Stop'
$js=@'
const version=await(await fetch("http://127.0.0.1:17447/json/version")).json();
const ws=new WebSocket(version.webSocketDebuggerUrl);
await new Promise((ok,no)=>{ws.addEventListener("open",ok,{once:true});ws.addEventListener("error",no,{once:true})});
const url="https://www.avito.ru/krasnoyarsk/doma_dachi_kottedzhi/sdam/posutochno";
const p=new Promise((ok,no)=>{ws.addEventListener("message",e=>{try{const x=JSON.parse(e.data);if(x.id===201)ok(x)}catch{} });setTimeout(()=>no(Error("CDP_TIMEOUT")),7500)});
ws.send(JSON.stringify({id:201,method:"Target.createTarget",params:{url,background:true,newWindow:false}}));
const x=await p;ws.close();
console.log(JSON.stringify({ok:!!x.result?.targetId,target_id:x.result?.targetId||null,port:17447,error:x.error?.code||null}));
'@
$temp=Join-Path $env:TEMP 'pc-avito-managed-page-target.mjs'
try{[System.IO.File]::WriteAllText($temp,$js,[System.Text.UTF8Encoding]::new($false));& node.exe $temp}finally{Remove-Item -LiteralPath $temp -ErrorAction SilentlyContinue -Force}
